From Coq Require Import List String.
From Buri Require Import Wire Native.
Import ListNotations Native.Native.
Open Scope string_scope.
Definition order_call_text : string := "".
Definition order_call_nodes :=
 match Wire.decode_text order_call_text with
 | Some (Wire.Cons (Wire.Atom false "buri-constructor-native-1") (Wire.Cons tagged Wire.Nil)) =>
   match untag 500 tagged with Some root => elements root | _ => None end
 | _ => None end.
Definition order_call_decode := match order_call_nodes with
 | Some xs => definitions 500 (firstn 6 (skipn 0 xs)) | None => None end.
Definition order_call_program := Eval vm_compute in
 match order_call_decode with Some ds => ds | None => [] end.
Theorem order_call_exact : order_call_decode = Some order_call_program.
Proof. vm_compute. reflexivity. Qed.
Theorem order_call_names : map fst order_call_program = ["kl:_scm.merge-nested-lets";"kl:_scm.simple-scheme-expression?";"kl:_scm.has-computation?";"kl:_scm.fresh-call-variable";"kl:_scm.order-call-inputs";"kl:_scm.order-call"].
Proof. vm_compute. reflexivity. Qed.
Global Opaque order_call_text order_call_nodes order_call_decode.
